INSERT INTO `inabuyer_messages` VALUES (2,'Priscilla','Universitas Gajah Mada',NULL,NULL,NULL,'Bagus dan sangat menarik ingin dikunjungi lagi',0,'2026-05-04 18:56:46','2026-05-05 09:52:55'),(4,'Iswandi','Asosiasi pengusaha Engineering Karawang',NULL,NULL,NULL,'Semangat... Semoga lancar',1,'2026-05-05 09:52:20','2026-05-05 09:52:20'),(5,'Kadek Wisnawa','Inkubator Bisnis Universitas Udayana',NULL,NULL,NULL,'Terima kasih Pak prof Bayu Saya dari inkubator bisnis Udayana telah disambut dengan sangat baik dan juga diberikan buku ya pemrosesan Citra digital dari pidato pengukuhan guru besarnya Jadi terima kasih banyak mudah-mudahan ke depan bisa bekerja sama antara inkubator bisnis kami dan tentunya dengan pengembangan keilmuan dari Prof Bayu Terima kasih sukses selalu',1,'2026-05-05 09:55:51','2026-05-05 09:58:45'),(6,'Ahmad','PLN',NULL,NULL,NULL,'Menarik karena ada dari institusi pendidikan bisa ikut acara inabuyer, semoga dari karya-karya publikasi bisa terus maju untuk komersialisasi',1,'2026-05-05 10:14:19','2026-05-05 10:14:19'),(7,'Muhammad Ilham','Pemerintah Daerah Kabupaten Kutai Kartanegara',NULL,NULL,NULL,'Spin off dari UGM ini semoga berkembang dan bakal diperjualbelikan komersil dan semoga bermanfaat untuk masyarakat yang ada di Indonesia',1,'2026-05-05 10:22:35','2026-05-05 10:22:35'),(8,'Riza','Kementrian UMKM',NULL,NULL,NULL,'Untuk produknya sudah asli dari Indonesia produknya Semoga nanti bisa berkembang selanjutnya',1,'2026-05-05 10:26:53','2026-05-05 10:26:53'),(9,'Nadimin','Pegadaian Kebayoran Baru',NULL,NULL,NULL,'Uji dengan x-ray pada proses produksi suatu produk dapat meningkatkan trust kepada konsumen terhadap hasil produk yang dimiliki suatu badan usaha',1,'2026-05-05 10:32:24','2026-05-05 10:32:24'),(10,'Emi Nur Jannah','Emi house',NULL,NULL,NULL,'Aku bangga ada karya indonesia yang seperti ini',1,'2026-05-05 10:42:09','2026-05-05 10:42:09'),(11,'Andrian','Kementerian Umkm',NULL,NULL,NULL,'Acaranya bagus dan banyak perusahaan perusahaan potensial dengan produl yang berdaya saing',1,'2026-05-05 10:45:22','2026-05-05 10:45:22'),(12,'Abdul Fattah','PT FHM',NULL,NULL,NULL,'Luar biasa luar biasa',1,'2026-05-05 10:46:26','2026-05-05 10:46:26'),(13,'Abdul Fattah','PT FHM',NULL,NULL,NULL,'Luar biasa luar biasa',1,'2026-05-05 10:46:29','2026-05-05 10:46:29'),(14,'Rudi','Furniture',NULL,NULL,NULL,'Bagus kalau universitas mau turun ke industri',1,'2026-05-05 10:50:01','2026-05-05 10:50:01'),(15,'Nadia','Kementerian Pertahanan',NULL,NULL,NULL,'Kesan Dan Pesannya Semoga Madinah Makin Sukses Bisa Menembus Pasar Ekspor Bisa Menjaga Ketahanan Industri Di Dalam Negeri',1,'2026-05-05 10:52:10','2026-05-05 10:52:10'),(16,'Nanda','Ikatan Ahli Pengadaan Indonésia',NULL,NULL,NULL,'Mungkin boleh dibikin kegiatan juga contohnya kayak activation ada games gitu jadi biar menarik',1,'2026-05-05 10:57:19','2026-05-05 10:57:19'),(17,'Tri','Umkm Malang',NULL,NULL,NULL,'Saya baru pertama kali ini, Ada x-ray-nya untuk produk umkmt ini hal baru buat saya harapan saya nanti akan lebih tersosialisasi lagi untuk tingkat UMKM agar produk UMKM juga bisa tercampur dari sisi apa uji-uji hiegenis yang bisa dilihat dari sisi seperti itu ya',1,'2026-05-05 11:03:57','2026-05-05 11:03:57'),(18,'Akbar','PT Raja Rasa Kuliner',NULL,NULL,NULL,'Menarik ada beberapa inovasi yang bisa berguna untuk perkembangan FnB terima kasih',1,'2026-05-05 11:09:41','2026-05-05 11:09:41'),(19,'Aditya Barnes','Binar',NULL,NULL,NULL,'Untuk inovasinya luar biasa terutama di industri yang memang bisa menjadi manfaat dan memang yang bisa membantu industri tersebut menganalisis berbagai sumber daya yang memang dibutuhkan industri tersebut dan inovasi ini bisa membantu di dunia manufaktur terutama untuk menganalisis kalori yang dibutuhkan sumber daya pembakaran yang dibutuhkan si industri tersebut',1,'2026-05-05 11:13:18','2026-05-05 11:13:18'),(20,'Dimitri Ahmad S','Xavortree',NULL,NULL,NULL,'Inovasi yang menarik dan sangat inovatif sekali untuk di kembangkan dan explorasi lebih untuk Scala besar di industri terutama di manufaktur',1,'2026-05-05 11:34:30','2026-05-05 11:34:30'),(21,'faldan','BRI',NULL,NULL,NULL,'Dari BRI tertarik untuk kerja sama dengan skema CSR untuk pengadaan x-ray di rumah sakit',1,'2026-05-05 11:40:49','2026-05-05 11:40:49'),(22,'Bernica','PT Hongsen Environmental Protection',NULL,NULL,NULL,'Insightful sekali karena ada teknologi baru selain xray yang saya ketahui pada umumnya. Kakaknya lucu dan informatif menjelaskan teknologi baru mengenai scan xray yg bisa dilakukan tidak hanya untuk badan saja. Terima kasih banyak kak',1,'2026-05-05 11:51:06','2026-05-05 11:51:06'),(23,'Helen','Visitor',NULL,NULL,NULL,'Jadi lebih simpel ya alatnya mungkin di klinik klinik yang sederhana bisa dipakai gitu jadi ada kemungkinan mungkin saya juga bisa digunakan lagi juga sistemnya peminjaman ya tidak memberatkan',1,'2026-05-05 12:04:52','2026-05-05 12:04:52'),(24,'Mahri','Kementerian Umkm',NULL,NULL,NULL,'Iya ini teknologinya teknologi yang menjanjikan gitu untuk masa depan kemudian dan ini sudah bisa bersaing untuk teknologi-teknologi yang memang produknya dari apa dibuat oleh negara-negara maju jadi sukses untuk Madinah karya Indonesia dari UGM terima kasih',1,'2026-05-05 12:05:27','2026-05-05 12:05:27'),(25,'Ratih K Diredja','PT Prospera Tekno Kreasi',NULL,NULL,NULL,'luar biasa ada produk dalam negeri sebaik ini. semoga bisa semakin berkembang dan semakin byk rs menggunakan produk madeena 👍',1,'2026-05-05 12:49:51','2026-05-05 12:49:51'),(26,'Suharto','Umkm',NULL,NULL,NULL,'Sangat bagus',1,'2026-05-05 13:12:02','2026-05-05 13:12:02'),(27,'Muslih','SMK Wikrama Bogor',NULL,NULL,NULL,'Produknya luar biasa ini perlu dikembangkan untuk lebih banyak varian kali ya tapi sudah hampir semua varian ya dalam hal ini namun ini menjadi apa ya bagi kami sesuatu yang bagus dan dikembangkan dan akan membantu masyarakat dalam hal ini gitu ya jadi pesannya adalah lanjutkan kembangkan kembali lebih luas lagi untuk variannya dan tentunya lebih mungkin bagi hasilnya lebih menguntungkan begitu.',1,'2026-05-05 13:49:57','2026-05-05 13:49:57'),(28,'Citra','Visitor Independent',NULL,NULL,NULL,'Untuk PT Madinah karya Indonesia tidak ada tidak ada apa namanya tidak ada yang kekurangan semuanya baik paling ditambah untuk keterangan yang jaganya seperti kartu nama ya atau yang bisa dibagiin ke customer-customer atau Victor yang datang seperti itu',0,'2026-05-05 14:16:31','2026-05-05 15:01:34'),(30,'Tyto Mulyono','Tazakaelektrik','PT. Tazakaelektrik','085220851888','tyto@tazaka.co.id','Ini karya anak bangsa yang keren. Belum menemukan alat radiografi dalam negeri yang memilik potensi yang sangat bagus dalam industri dan harus didukung oleh pemerintah. Terima kasih.',1,'2026-05-06 10:00:07','2026-05-06 10:00:07'),(31,'Kunto Wibowo','PT Tri Cipta Teknindo','Manager Marketing','0811858346','wibowo_kunto@yahoo.com','Bagus teknologi lokal dimana saya baru tahu, thank you',1,'2026-05-06 11:54:27','2026-05-06 11:54:27'),(32,'Hatma Ardana Reswari','CV Dekayu INDONESIA','Relation Manager','082143966526','askdekayu@gmail.com','Penjelasannya jelas, detail, menarik. Semiga Xray nya bisa menjangkau seluruh faskes 1 di Indonesia.',1,'2026-05-06 12:30:29','2026-05-06 12:30:29'),(33,'Priamboro','Brin','Rekayasa','08129680964','tetst@test.com','Menarik inovasi. Semoga dipermudah urusannya terutama terkait perijinan dll.',1,'2026-05-06 13:31:20','2026-05-06 13:31:20'),(34,'Gabriel Baki','TagflowAI, Inc','Co Founder','085885853177','gabriel@tagflow-ai.com','Sungguh canggih, saya mau coba gunakan.  Mari kerjasama membangun Indonesia.',1,'2026-05-06 14:33:46','2026-05-06 14:33:46'),(35,'Destia Riani','PT. Fadhil Damar Putra','Business Development','082273417911','destia.riani1215@gmail.com','Bagus inovatif produknya terus kembangkan.',1,'2026-05-06 15:35:53','2026-05-06 15:35:53'),(36,'Bagus Rahman','Deputi Kementerian UMKM','Deputi Bidang Usaha',NULL,NULL,'Halo assalamualaikum warahmatullahi wabarakatuh nama saya Bagus Rahman saya diputih bidang usaha menengah kementerian usaha mikro kecil menengah pertama tentunya apresiasi kepada PT.Madeena dan UGM ikut dalam acara Inabuyer ini. Temuan ini yang memang sempat disampaikan ke tempat saya ini menjadi penting ya khususnya tentunya di bidang kesehatan dan industri. tentunya para mahasiswa yang memang punya ide-ide kreatif seperti membuat produk untuk kesehatan dan industri nih sangat penting karena itu menjadi bagian yang paling krusial ya bagi masyarakat Indonesia Saya pikir apa yang dilakukan oleh perguruan tinggi dan PT.madeena ini harus bisa dihubungkan dengan industri ya khususnya pada UMKM yang memang nanti secara supply-nya juga ikut membantu hulu ke hilirnya dan yang berikutnya tentunya dengan rumah sakit umum daerah dulu deh, yang memang dia bisa e memanfaatkan produk ini nanti bisa menambah lagi ke rumah sakit swasta lainnya ya. sukses untuk PT. Madeena karya Indonesia dan MIPA UGM. Terima kasih assalamualaikum warahmatullahi wabarakatuh',1,'2026-05-06 15:48:59','2026-05-06 15:48:59'),(37,'Rudi','Bisnis Souvenir',NULL,'-','aa@aaa','Untuk produk ini cocok sekali untuk di klinik yang masih belum banyak ada radiologi dan mungkin untuk biaya cek up yang lebih murah',1,'2026-05-06 16:03:08','2026-05-06 16:03:08'),(38,'Yusril Ihza Tachriri','ITSNU Pekalongan','Dosen Fisika','082332337659','ihza.yusril24@gmail.com','Ya bismillahirrahmanirrahim assalamualaikum warahmatullahi wabarakatuh saya Yusril dari dosen di Pekalongan. produk radiografi digital yang dari PT Madeena karya Indonesia sangat bagus untuk penerapan proteksi dan otentikasi produk-produk yang ada di Pekalongan seperti batik dalam bentuk makanan instan atau kaleng sangat bagus seperti itu produk ini bisa tersebar di seluruh Indonesia dan kolaborasi riset terima kasih wassalamualaikum warahmatullahi wabarakatuh.',1,'2026-05-06 16:10:09','2026-05-06 16:10:09'),(39,'Fajar','Sekretaris Nasional SDGs','Sekretaris Nasional SDGs','08128099527','a@a','Ini adalah inovasi baru, inovasi terbaik yang bisa dimanfaatkan oleh masyarakat kita.',1,'2026-05-06 17:34:13','2026-05-06 17:34:13'),(40,'drg. ridwan silitonga, SPBMM','RSUD lembang','PNS Bandung','081247036003','daomaraspbmm1406@gmail.com','belajar ilmu x-ray di booth, semoga produk dalam negeri semakin mendunia amin',1,'2026-05-07 11:21:08','2026-05-07 11:21:08'),(41,'Reza','PT Natadwipa','GM','081220415834','reza.nurrahman@gmail.com','Semangat, Mesin X-ray Indonesia harus jaya!',1,'2026-05-07 12:05:48','2026-05-07 12:05:48'),(42,'Ananda','Apotek Dokter Mandiri',NULL,'085121366002','apotekloyal@gmail.com','Sudah sudah baik bisa masuk dalam InaBuyer sehingga bisa bertemu dengan pelaku usaha di bidang kesehatan mungkin bisa ditambahkan informasi yang bisa langsung dipakai oleh diindustri kesehatan seperti apotek makasih',1,'2026-05-07 12:26:59','2026-05-07 12:26:59'),(43,'David','Alami Syariah',NULL,'0895376738420',NULL,'Sukses mengingat ini usahanya udah cukup lama ya jadi untuk segala jenis produk-produk yang memang mungkin sudah editing maupun yang mungkin lagi sedang dicari mungkin inovatifnya tetap di tetap dikembangkan aja lagi yang satu sisi kan memang mungkin yang dibutuhkan tetap profit ya kan, misalkan dari itu mungkin coba carikan dari sisi customer lain yang memang repeat bukan sekedar baru tapi ujung-ujungnya mereka bisa bayar gitu jadi masih maka dari itu aja oke',1,'2026-05-07 14:19:31','2026-05-07 14:19:31'),(44,'Medi','Event Organizer Alat Kesehatan',NULL,NULL,NULL,'sangat kagum produksi indonesia yang sudah maju di bidang kesehatan',1,'2026-05-07 14:33:02','2026-05-07 14:33:02');
